using System.Collections.Generic;public class Solution{public IList<IList<int>> ZigzagLevelOrder(TreeNode r){var o=new List<IList<int>>();if(r==null)return o;var q=new Queue<TreeNode>();q.Enqueue(r);bool rev=false;while(q.Count>0){int n=q.Count;int[]v=new int[n];for(int i=0;i<n;i++){var x=q.Dequeue();v[rev?n-1-i:i]=x.val;if(x.left!=null)q.Enqueue(x.left);if(x.right!=null)q.Enqueue(x.right);}o.Add(v);rev=!rev;}return o;}}
